//! Cross-language golden vectors for the canonical binary patch format and the
//! id-keyed operations (tests/vectors/patch-binary-vectors.json, generated by
//! running apps/desktop/src/shared/patch-ids.ts and patch-binary.ts under bun).

use pm_model::Document;
use pm_model::binary::{decode, encode, is_canonical};
use pm_model::json::{self, Value, parse};
use pm_model::ops::{Op, apply_ops, diff_ops, ops_from_value};
use pm_model::patch::{PatchErrorKind, apply_patches, diff_patches};

fn vectors() -> Value {
    parse(include_str!("vectors/patch-binary-vectors.json")).expect("vector file parses")
}

fn unhex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// A document given as JSON text, or `None` for `undefined`.
fn doc(value: &Value) -> Option<Value> {
    match value {
        Value::Null => None,
        Value::String(text) => Some(parse(&text.to_string_lossy()).unwrap()),
        other => panic!("bad document {other:?}"),
    }
}

fn canonical(value: Option<&Value>) -> Option<String> {
    value.map(json::to_canonical_string)
}

fn field<'a>(case: &'a Value, key: &str) -> &'a Value {
    case.get(key).unwrap_or_else(|| panic!("missing {key}"))
}

#[test]
fn typescript_bytes_decode_reencode_and_match_the_rust_generator() {
    let vectors = vectors();
    assert_eq!(
        vectors.get("format").and_then(Value::as_str),
        Some("canonicalV1")
    );
    let cases = field(&vectors, "cases").as_array().unwrap();
    assert!(cases.len() >= 400, "expected the generated cases");
    let mut kinds = [0usize; 4];
    for case in cases {
        let name = field(case, "name").as_str().unwrap();
        let bytes = unhex(field(case, "hex").as_str().unwrap());
        let before = doc(field(case, "before"));
        let after = doc(field(case, "after"));

        // The TypeScript encoder's bytes decode to its operations.
        let decoded = decode(&bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
        let listed = ops_from_value(field(case, "ops")).unwrap();
        assert_eq!(decoded, listed, "{name}");
        // The Rust encoder writes the same bytes.
        assert_eq!(hex(&encode(&decoded).unwrap()), hex(&bytes), "{name}");
        assert!(is_canonical(&bytes), "{name}");
        // The Rust generator emits the same operations.
        assert_eq!(diff_ops(before.as_ref(), after.as_ref()), decoded, "{name}");

        for op in &decoded {
            kinds[match op {
                Op::Leaf(_) => 0,
                Op::Order { .. } => 1,
                Op::Insert { .. } => 2,
                Op::Delete { .. } => 3,
            }] += 1;
        }

        // Applying them gives `after`, as patch.ts's leaf patches do.
        let mut root = before.clone();
        apply_ops(&mut root, &decoded).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(
            canonical(root.as_ref()),
            canonical(after.as_ref()),
            "{name}"
        );
        let (leaf, _) = diff_patches(before.as_ref(), after.as_ref());
        let mut by_leaf = before.clone();
        apply_patches(&mut by_leaf, &leaf).unwrap();
        assert_eq!(
            canonical(by_leaf.as_ref()),
            canonical(after.as_ref()),
            "{name}"
        );

        // On the revisioned document: the same tree and revisions as the
        // leaf patches' id-keyed reconciliation.
        let mut by_ops = Document::new(before.clone(), 1);
        by_ops.apply_ops_at(&decoded, 2).unwrap();
        let mut reconciled = Document::new(before, 1);
        reconciled.apply_at(&leaf, 2).unwrap();
        assert_eq!(by_ops, reconciled, "{name}");
    }
    assert!(
        kinds.iter().all(|&n| n > 50),
        "every operation kind is covered: {kinds:?}"
    );
}

#[test]
fn apply_cases_match_typescript_results_and_errors() {
    let vectors = vectors();
    for case in field(&vectors, "applyCases").as_array().unwrap() {
        let name = field(case, "name").as_str().unwrap();
        let bytes = unhex(field(case, "hex").as_str().unwrap());
        let ops = decode(&bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(ops, ops_from_value(field(case, "ops")).unwrap(), "{name}");
        assert_eq!(hex(&encode(&ops).unwrap()), hex(&bytes), "{name}");

        let expected_error = field(case, "error").as_object().map(|e| {
            (
                e.get("index").unwrap().as_f64().unwrap() as usize,
                e.get("kind").unwrap().as_str().unwrap().to_owned(),
            )
        });
        let expected = doc(field(case, "result"));
        for revisioned in [false, true] {
            let (result, error) = if revisioned {
                let mut d = Document::new(doc(field(case, "doc")), 1);
                let error = d.apply_ops_at(&ops, 2).err();
                (d.to_value(), error)
            } else {
                let mut root = doc(field(case, "doc"));
                let error = apply_ops(&mut root, &ops).err();
                (root, error)
            };
            let error = error.map(|e| {
                let kind = match e.kind {
                    PatchErrorKind::Mismatch => "Mismatch",
                    PatchErrorKind::TypeError => "TypeError",
                    PatchErrorKind::RangeError => "RangeError",
                    PatchErrorKind::Limit => "Limit",
                };
                (e.index, kind.to_owned())
            });
            assert_eq!(error, expected_error, "{name}");
            assert_eq!(
                canonical(result.as_ref()),
                canonical(expected.as_ref()),
                "{name}"
            );
        }
    }
}

#[test]
fn invalid_bodies_are_rejected() {
    let vectors = vectors();
    let invalid = field(&vectors, "invalid").as_array().unwrap();
    assert!(invalid.len() > 20);
    for case in invalid {
        let name = field(case, "name").as_str().unwrap();
        let bytes = unhex(field(case, "hex").as_str().unwrap());
        assert!(decode(&bytes).is_err(), "{name} decoded");
        assert!(!is_canonical(&bytes), "{name}");
    }
}

#[test]
fn decoding_never_panics_on_mutated_vectors() {
    // Single-byte mutations and every truncation of every golden body fail
    // cleanly or decode to something that re-encodes.
    let vectors = vectors();
    let mut state = 0x2545_f491_4f6c_dd1du64;
    let mut next = || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    for case in field(&vectors, "cases")
        .as_array()
        .unwrap()
        .iter()
        .take(120)
    {
        let bytes = unhex(field(case, "hex").as_str().unwrap());
        for end in 0..bytes.len().min(400) {
            assert!(decode(&bytes[..end]).is_err());
        }
        for _ in 0..64 {
            let mut mutated = bytes.clone();
            let i = (next() % mutated.len() as u64) as usize;
            mutated[i] = next() as u8;
            if let Ok(ops) = decode(&mutated) {
                let again = encode(&ops).unwrap();
                assert_eq!(decode(&again).unwrap(), ops);
            }
        }
    }
}
